    async def kev_lookup(self, *, cve_id: str) -> dict[str, Any]:
        """CISA KEV Lookup

        CISA KEV catalog entry for a CVE: the required action, the patch deadline and
        known ransomware use. A CVE that CISA removed answers in_kev false, and one
        never listed answers "KEV entry not found".

        Costs 1 credit.

        Args:
            cve_id: CVE ID. At most 24 characters.
        """
        return await self.call("kev_lookup", {"cve_id": cve_id})

    async def cwe_lookup(self, *, cwe_id: str) -> dict[str, Any]:
        """CWE Lookup

        CWE weakness details (description, mitigations, examples), with how many CVEs
        and CISA KEV entries name it. To list them, call the cve_search tool with its
        cwe_id argument.

        Costs 1 credit.

        Args:
            cwe_id: CWE ID, e.g. CWE-79. At most 16 characters.
        """
        return await self.call("cwe_lookup", {"cwe_id": cwe_id})

    async def cve_risk_score(self, *, cve_id: str) -> dict[str, Any]:
        """CVE Risk Score

        Composite risk score of a CVE, from 0 to 100, for patch priority. It reads EPSS,
        CISA KEV, Metasploit, CVSS, NVD exploit references and ExploitDB. has_public_poc
        is null when no source names an exploit.

        Costs 1 credit.

        Args:
            cve_id: CVE ID. At most 24 characters.
        """
        return await self.call("cve_risk_score", {"cve_id": cve_id})

    async def cve_exploit(self, *, cve_id: str) -> dict[str, Any]:
        """CVE Exploit Intelligence

        Public exploit intelligence (GitHub PoCs, Metasploit, NVD exploit references,
        ExploitDB). GitHub PoC repositories are listed but not counted as proof of a
        public exploit.

        Costs 1 credit.

        Args:
            cve_id: CVE ID. At most 24 characters.
        """
        return await self.call("cve_exploit", {"cve_id": cve_id})

